"""A correlation id is generated by the API, never taken from the caller.

It is written into every audit event of a request, and the surfaces that take no session
record under the clinic the request names. A caller's `X-Correlation-ID` would be the caller's
own text in a clinic's append-only trail — and even an id-shaped one carries sixteen bytes of
the caller's choosing.
"""

from __future__ import annotations

import re

import pytest
from sqlalchemy import select, text

from hadp_api.modules.audit.models import AuditEvent
from hadp_api.modules.enums import Role
from tests.helpers import login_as, provision_staff

_GENERATED = re.compile(r"[0-9a-f]{32}")
FREE_TEXT = "Erika Mustermann, HbA1c 9,1 %, geb. 01.02.1960"
# "Erika Mustermann" in hexadecimal: shaped like an id, and still somebody's text.
HEX_TEXT = "4572696b61204d75737465726d616e6e"


@pytest.mark.parametrize(
    "supplied",
    [
        FREE_TEXT,
        HEX_TEXT,
        "0123ABCD-89ab-4def-8123-456789abcdef",
        "<img src=x onerror=alert(1)>",
        "a" * 5000,
        "",
    ],
)
def test_the_callers_id_is_never_used(client, supplied: str) -> None:  # type: ignore[no-untyped-def]
    first = client.get("/api/v1/health", headers={"x-correlation-id": supplied})
    second = client.get("/api/v1/health", headers={"x-correlation-id": supplied})

    for answered in (first.headers["x-correlation-id"], second.headers["x-correlation-id"]):
        assert _GENERATED.fullmatch(answered)
        assert answered != supplied.lower()
    assert first.headers["x-correlation-id"] != second.headers["x-correlation-id"]


@pytest.mark.parametrize("supplied", [FREE_TEXT, HEX_TEXT])
def test_a_caller_without_a_session_cannot_write_into_a_clinics_trail(  # type: ignore[no-untyped-def]
    client, admin_session, supplied: str
) -> None:
    _user, tenant = provision_staff(
        admin_session,
        email="owner-planted@synthetic.example",
        tenant_name="Audit Planted",
        tenant_slug="audit-planted",
        role=Role.OWNER,
    )

    body = {"tenant": str(tenant.id), "token": "x" * 20}
    new_member = {"display_name": "Synthetic Nobody", "email": "nobody@synthetic.example"}
    for path, extra in (
        ("/api/v1/invitations/redeem", {}),
        ("/api/v1/staff-invitations/redeem", new_member),
    ):
        resp = client.post(path, headers={"x-correlation-id": supplied}, json={**body, **extra})
        assert resp.status_code == 404, (path, resp.text)

    denied = admin_session.execute(
        select(AuditEvent).where(AuditEvent.tenant_id == tenant.id)
    ).scalars()
    recorded = {event.action: event.correlation_id for event in denied}
    assert set(recorded) == {"invitation.redeem_denied", "staff_invite.redeem_denied"}
    for correlation_id in recorded.values():
        assert correlation_id and _GENERATED.fullmatch(correlation_id)
        assert correlation_id != supplied
    planted = admin_session.execute(
        text(
            "SELECT count(*) FROM audit_events "
            "WHERE audit_events::text ILIKE '%Mustermann%' OR correlation_id = :hex"
        ),
        {"hex": HEX_TEXT},
    ).scalar_one()
    assert planted == 0


def test_a_long_header_does_not_break_an_audited_request(client, admin_session) -> None:  # type: ignore[no-untyped-def]
    """The column holds 64 characters; a longer id used to fail the audit write, and with it
    the request."""
    login_as(
        client,
        admin_session,
        email="owner-long@synthetic.example",
        tenant_name="Audit Long",
        tenant_slug="audit-long",
        role=Role.OWNER,
    )

    resp = client.get("/api/v1/patients", headers={"x-correlation-id": "a" * 200})

    assert resp.status_code == 200
    listed = admin_session.execute(
        select(AuditEvent).where(AuditEvent.action == "patient.list")
    ).scalar_one()
    assert listed.correlation_id == resp.headers["x-correlation-id"]
    assert _GENERATED.fullmatch(listed.correlation_id)


def test_a_refused_cross_site_request_records_no_caller_text(client, admin_session) -> None:  # type: ignore[no-untyped-def]
    login_as(
        client,
        admin_session,
        email="owner-csrf@synthetic.example",
        tenant_name="Audit Csrf",
        tenant_slug="audit-csrf",
        role=Role.OWNER,
    )
    client.headers.pop("x-csrf-token")

    resp = client.post(
        "/api/v1/patients",
        json={"display_name": "Synthetic Cross Site"},
        headers={"x-correlation-id": HEX_TEXT},
    )

    assert resp.status_code == 403
    refused = admin_session.execute(
        select(AuditEvent).where(AuditEvent.action == "csrf.denied")
    ).scalar_one()
    assert refused.correlation_id is None
